const sidebars = $('Get Sidebars').all().map(i => i.json);
const widgets = $('Get Widgets').all().map(i => i.json);

// Find widgets matching footer + with legal links
const findLegal = (text) => {
  if (!text) return [];
  const matches = [];
  for (const slug of ['privacy-policy','aviso-legal','terminos-y-condiciones','politica-de-cookies','politica-de-privacidad']) {
    if (text.includes('/' + slug + '/') || text.includes(slug)) matches.push(slug);
  }
  return matches;
};

const footerSidebars = sidebars.filter(s => /footer|pie/i.test(s.id) || /footer|pie/i.test(s.name));
const footerWidgets = widgets.filter(w => /^(footer|sidebar-secondary)/i.test(w.sidebar || ''));
const allHits = [];
for (const w of footerWidgets) {
  const raw = JSON.stringify(w.rendered || '') + ' ' + JSON.stringify(w.instance?.raw || {});
  const hits = findLegal(raw);
  if (hits.length) {
    allHits.push({ id: w.id, sidebar: w.sidebar, idBase: w.id_base, hits, rendered_excerpt: (w.rendered||'').slice(0, 300) });
  }
}

const lines = [];
lines.push('SIDEBARS (' + sidebars.length + ' total):');
for (const s of sidebars) lines.push('  ' + s.id + ' [' + s.name + '] widgets=' + (s.widgets?.length||0));
lines.push('');
lines.push('FOOTER SIDEBARS: ' + footerSidebars.map(s=>s.id).join(', '));
lines.push('');
lines.push('WIDGETS EN FOOTER (' + footerWidgets.length + '):');
for (const w of footerWidgets) {
  const raw = (w.rendered || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  lines.push('  ['+w.sidebar+'] ' + w.id + ' (type=' + w.id_base + ')');
  lines.push('    text: ' + raw.slice(0, 200));
}
lines.push('');
lines.push('WIDGETS CON ENLACES LEGALES (' + allHits.length + '):');
for (const h of allHits) {
  lines.push('  • ' + h.id + ' (sidebar=' + h.sidebar + ', type=' + h.idBase + ')');
  lines.push('    hits: ' + h.hits.join(','));
  lines.push('    excerpt: ' + h.rendered_excerpt.replace(/\s+/g, ' ').slice(0,200));
}

// Get content of key widgets for inspection
const keyIds = ['block-10', 'text-2', 'text-3', 'nav_menu-1', 'block-8', 'block-9'];
const inspection = {};
for (const id of keyIds) {
  const w = widgets.find(x => x.id === id);
  if (w) inspection[id] = { sidebar: w.sidebar, type: w.id_base, rendered: (w.rendered||'').slice(0,1200), instance_raw_keys: Object.keys(w.instance?.raw||{}) };
}
return [{ json: { report: lines.join('\n'), inspection } }];

